script:
stage(1000, 600, "#fbfbf8");
title({hu: "Változó nyíl", en: "Changing arrow"});
param("Imax", {hu: "Csúcsáram Î", en: "Peak current Î"}, 0, 10, 8, 0.1, "A");
param("f", {hu: "Frekvencia f", en: "Frequency f"}, 0.05, 2, 0.25, 0.05, "Hz");
let i = 0;
update((dt, t) => { i = P.Imax * sin(2 * PI * P.f * t); });
boundArrow("i-nyíl", {
  x: 500, y: 300,
  angle: 0,
  length: "30 * i",
  width: "2 + abs(i)",
  color: "#2f6fd6",
  colorBy: "abs(i)",
  colorMin: 0, colorMax: 10,
  colorTo: "#d64045",
  label: "i = {i:1} A"
});
draw(t => {
  line(500, 150, 500, 450, {stroke: C.light, lw: 1, dash: [4, 4]});
  circle(500, 300, 6, {fill: C.ink});
  show({hu: "Áram i", en: "Current i"}, i, "A");
  plot("i", i, {unit: "A", color: C.blue});
  val({i});
});
